mapper.update:
UPDATE chat_room_member
SET last_read_at = now()
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM chat_room_member
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}

mapper.update:
UPDATE chat_message
SET deleted_at = now()
WHERE message_idx = #{messageIdx}
  AND sender_id = #{senderId}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM chat_room_member
WHERE room_idx = #{roomIdx}
  AND user_id = #{userId}
